/** True Chromium + actual Pyodide converter end-to-end R4B multi-writer test.
 * Synthetic source fixture generated by the existing Python converter.
 * Actual Owner GLRD inputs are not copied to the public Git repository.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { chromium } from 'playwright';

const root=path.resolve(import.meta.dirname,'..');
const fixture=path.resolve(root,'tests/.r4b-two-writer-runtime');
const server=createServer(async(req,res)=>{
  try {
    const name=decodeURIComponent(new URL(req.url,'http://127.0.0.1').pathname);
    const resolved=path.resolve(root,'.'+name);
    if(!resolved.startsWith(root+path.sep)){res.writeHead(403);res.end();return;}
    const bytes=await readFile(resolved);
    res.setHeader('Content-Type',/\.(?:mjs|js)$/.test(resolved)?'application/javascript':
      /\.wasm$/.test(resolved)?'application/wasm':
      /\.html$/.test(resolved)?'text/html':
      /\.xml$/.test(resolved)?'application/xml':'application/octet-stream');
    res.end(bytes);
  }catch(e){res.writeHead(404);res.end(e.message);}
});
await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));
const origin='http://127.0.0.1:'+server.address().port;
const browser=await chromium.launch({headless:true,args:['--no-sandbox']});
const page=await browser.newPage({acceptDownloads:true,viewport:{width:1460,height:950}});
page.setDefaultTimeout(240000);
const errors=[];page.on('pageerror',error=>errors.push(String(error)));
try {
 await test('R4B real Chromium/Pyodide: two writer nodes, preview 150 to 26 N, preserve other 150 N, approved XML edit + downloads',async()=>{
   await page.goto(origin+'/tests/fixtures/r2-source-weight-browser-host.html');
   const found=await page.evaluate(async()=>{
     const xml=await fetch('/tests/.r4b-two-writer-runtime/original.xml').then(r=>r.text());
     const cii=await fetch('/tests/.r4b-two-writer-runtime/original.cii').then(r=>r.text());
     const {ciiSha256}=await import('/tabs/xml-cii-2019-standalone/xml-cii-final-property-reader.js');
     const {initializeSourceWeightSession}=
       await import('/tabs/xml-cii-2019-standalone/xml-cii-source-weight-reextract.js');
     const run={ok:true,ciiText:cii,ciiName:'r4b-two-writer.cii',
       ciiInputSource:'original',
       finalRigidReviewEvidence:{
         sourceKind:'xml',engineInputText:xml,
         engineInputSha256:await ciiSha256(xml),
         originalCiiSha256:await ciiSha256(cii),
         engineInputDigest:'R4A_SYNTHETIC_CURRENT_WRITER',
         effectiveSourceName:'r4b-two-writer.xml',weightScale:10,
         supportConfigJson:'{}',stagedJsonText:'',
         effectiveOptions:{coordsMode:'first',kgToNewton:true,
           splitCondensedValveFlange:true,useRestraintTypeBasedOnJson:true,
           outputMode:'both',analyzeTopology:false,
           generateTopoFix:false,useTopoFixForCii:false},
       },
     };
     const session=await initializeSourceWeightSession(run,{requireR4aLineage:true});
     const writer=session.verifiedLineage.sourceNodes.find(x=>x.originalNodeNumber==='40'&&
       x.componentRefNo==='/SHARED-COMP');
     const pointer=session.verifiedLineage.auxiliaryRecords
       .find(x=>x.writerWeightSourceNode===writer.identity).recordPointer;
     window.__r4b={run,session,pointer};
     const {openFinalRigidWeightReview}=await import(
       '/tabs/xml-cii-2019-standalone/ui-adapted/xml-cii-adapted-final-rigid-review.js');
     openFinalRigidWeightReview(run,{getCurrentResult:()=>run});
     return {pointer,originalCiiSha:await ciiSha256(cii),
       originalXmlSha:await ciiSha256(xml),
       row:session.rows.find(x=>x.rigidPointer===pointer)};
   });
   assert.equal(found.row.eligible,false,'R4A must still hold two writers');
   assert.equal(found.row.reasonCode,'SOURCE_OWNER_AMBIGUOUS');
   await page.locator('[data-source-weight-open]').click();
   await page.waitForFunction(()=>document.querySelector('[data-source-weight-status]')?.textContent.includes('PASS:'),
     null,{timeout:240000});
   await page.locator('[data-source-weight-search]').fill(String(found.pointer));
   await page.locator('[data-source-weight-pointer]').selectOption(String(found.pointer));
   assert.equal(await page.locator('[data-source-weight-value]').isDisabled(),false,
     'R4B must offer read-only dependency probing despite original R4A hold');
   assert.equal(await page.locator('[data-source-weight-r4b-plan]').isVisible(),true);
   await page.locator('[data-source-weight-value]').fill('2.6');
   await page.locator('[data-source-weight-preview]').click();
   await page.waitForFunction(()=>document.querySelector('[data-source-weight-report]')?.
     textContent.includes('R4B REAL-CONVERTER ISOLATION TRIAL: PASS'),null,{timeout:240000});
   assert.equal(await page.locator('[data-source-weight-apply]').isDisabled(),true,
     'Unapproved physical group total and missing reference must block Apply');
   const preview=await page.locator('[data-source-weight-report]').textContent();
   assert.match(preview,/150 → 26 N/);
   assert.match(preview,/30 kg/);
   assert.match(preview,/17.6 kg/);
   await page.locator('[data-source-weight-r4b-total]').fill('17.6');
   await page.locator('[data-source-weight-r4b-basis]').fill('Signed engineering test allocation AUTH-35-36');
   await page.locator('[data-source-weight-owner-approved]').check();
   await page.locator('[data-source-weight-approved]').check();
   await page.locator('[data-source-weight-preview]').click();
   await page.waitForFunction(()=>document.querySelector('[data-source-weight-report]')?.
     textContent.includes('R4B REAL-CONVERTER ISOLATION TRIAL: PASS'),null,{timeout:240000});
   assert.equal(await page.locator('[data-source-weight-apply]').isDisabled(),false);
   await page.locator('[data-source-weight-apply]').click();
   await page.waitForFunction(()=>document.querySelector('[data-source-weight-report]')?.
     textContent.includes('VERIFIED SOURCE-BACKED RE-EXTRACTION'),null,{timeout:240000});
   const expectedXml=await readFile(path.join(fixture,'approved.xml'),'utf8');
   const expectedCii=await readFile(path.join(fixture,'approved.cii'),'utf8');
   for(const [type,expected] of [['revised-xml',expectedXml],['revised-cii',expectedCii]]){
     const b=page.locator('[data-source-weight-'+type+']');
     assert.equal(await b.isDisabled(),false);
     const [download]=await Promise.all([page.waitForEvent('download'),b.click()]);
     assert.equal(await readFile(await download.path(),'utf8'),expected);
   }
   const [download]=await Promise.all([
     page.waitForEvent('download'),page.locator('[data-source-weight-audit]').click()]);
   const audit=JSON.parse(await readFile(await download.path(),'utf8'));
   assert.equal(audit.schema,'xml-cii-r4b-isolated-source-weight-audit/v1');
   assert.equal(audit.originalCiiSha256,found.originalCiiSha);
   assert.equal(audit.originalEngineXmlSha256,found.originalXmlSha);
   assert.equal(audit.memberAllocations.length,2);
   assert.equal(audit.originalEmittedGroupKg,30);
   assert.equal(audit.revisedEmittedGroupKg,17.6);
   assert.equal(audit.ciiEngineeringDiff.expectedDifferences.length,1);
   assert.equal(audit.ciiEngineeringDiff.unexpectedDifferences,0);
   assert.equal(audit.physicalMassAuthority,'USER_ATTESTED_NOT_INDEPENDENTLY_VALIDATED');
   assert.deepEqual(errors,[],errors.join('\n'));
 });
} finally {
 await browser.close();
 await new Promise(resolve=>server.close(resolve));
}
